interface ParticleInfo {
  x: number
  y: number
  size: number
  color: Color
  angle: number
  speed: number
}

/**
 * SVG Advanced Effects Example - Demonstrates comprehensive SVG advanced effects
 * Including: filters, masks, clipping, gradients, transforms, animations, particles
 */
@Entry
@Component
struct svgExample018 {
  @State blurRadius: number = 0
  @State shadowRadius: number = 0
  @State shadowColor: Color = Color.Black
  @State gradientAngle: number = 0
  @State rotateAngle: number = 0
  @State scaleValue: number = 1.0
  @State translateX: number = 0
  @State translateY: number = 0
  @State animationDuration: number = 1000
  @State isAnimating: boolean = false
  @State brightnessValue: number = 1.0
  @State contrastValue: number = 1.0
  @State saturateValue: number = 1.0
  @State invertValue: number = 0
  @State sepiaValue: number = 0
  @State hueRotateValue: number = 0
  @State glowIntensity: number = 0.5
  @State embossStrength: number = 0
  @State sharpenAmount: number = 0
  @State animAngle: number = 0
  @State animScale: number = 1.0
  @State animOpacity: number = 1.0
  @State animX: number = 0
  @State progress: number = 0
  @State interactScale: number = 1.0
  @State interactOpacity: number = 1.0
  @State interactRotation: number = 0
  @State interactColor: Color = Color.Blue
  @State pressCount: number = 0
  @State dragX: number = 0
  @State dragY: number = 0
  @State loadAngle1: number = 0
  @State loadAngle2: number = 0
  @State loadAngle3: number = 0
  @State loadOpacity1: number = 1.0
  @State loadOpacity2: number = 1.0
  @State loadOpacity3: number = 1.0
  @State loadScale1: number = 1.0
  @State loadScale2: number = 1.0
  @State loadScale3: number = 1.0
  @State transitionIndex: number = 0
  @State particles: ParticleInfo[] = []
  private colors: Color[] = [
    Color.Red, Color.Orange, Color.Yellow, Color.Green,
    Color.Black, Color.Blue, Color.Transparent, Color.Pink,
    Color.Brown, Color.Gray
  ]
  private gradientColors: Array<[ResourceColor, number]> = [
    [Color.Red, 0.0],
    [Color.Orange, 0.25],
    [Color.Yellow, 0.5],
    [Color.Green, 0.75],
    [Color.Blue, 1.0]
  ]

  aboutToAppear(): void {
    this.initParticles()
  }

  private initParticles(): void {
    const tempParticles: ParticleInfo[] = []
    for (let i = 0; i < 20; i++) {
      const particle: ParticleInfo = {
        x: Math.random() * 280,
        y: Math.random() * 280,
        size: 10 + Math.random() * 30,
        color: this.colors[Math.floor(Math.random() * 6)],
        angle: Math.random() * 360,
        speed: 1 + Math.random() * 3
      }
      tempParticles.push(particle)
    }
    this.particles = tempParticles
  }

  build() {
    Scroll() {
      Column({ space: 20 }) {
        Text('SVG Advanced Effects Example')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .margin({ top: 20, bottom: 10 })

        this.BlurEffectSection()
        this.ShadowEffectSection()
        this.GradientEffectSection()
        this.TransformEffectSection()
        this.AnimationEffectSection()
        this.MaskEffectSection()
        this.ClipEffectSection()
        this.FilterEffectSection()
        this.ParticleEffectSection()
        this.ProgressEffectSection()
        this.GlowEffectSection()
        this.EmbossEffectSection()
        this.SharpenEffectSection()
        this.ColorMatrixEffectSection()
        this.MixedEffectSection()
        this.InteractiveEffectSection()
        this.LoadingEffectSection()
        this.TransitionEffectSection()
      }
      .width('100%')
      .padding(15)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }

  @Builder
  BlurEffectSection() {
    Column({ space: 15 }) {
      Text('Blur Effect')
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .width('100%')

      Row({ space: 15 }) {
        Column({ space: 5 }) {
          Image($r('app.media.testSvg'))
            .width(80)
            .height(80)
            .blur(this.blurRadius)
            .border({ width: 1, color: Color.Gray })
          Text('Blur: ' + this.blurRadius.toFixed(0))
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.svg'))
            .width(80)
            .height(80)
            .blur(this.blurRadius * 0.5)
            .border({ width: 1, color: Color.Gray })
          Text('Half Blur')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.icon'))
            .width(80)
            .height(80)
            .blur(this.blurRadius * 1.5)
            .border({ width: 1, color: Color.Gray })
          Text('1.5x Blur')
            .fontSize(12)
        }
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)

      Slider({
        value: this.blurRadius,
        min: 0,
        max: 20,
        step: 1
      })
        .width('90%')
        .onChange((value: number) => {
          this.blurRadius = value
        })

      Text('Adjust blur radius')
        .fontSize(12)
        .fontColor(Color.Gray)
    }
    .width('100%')
    .padding(10)
    .backgroundColor(Color.White)
    .borderRadius(10)
  }

  @Builder
  ShadowEffectSection() {
    Column({ space: 15 }) {
      Text('Shadow Effect')
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .width('100%')

      Row({ space: 15 }) {
        Column({ space: 5 }) {
          Image($r('app.media.testSvg'))
            .width(70)
            .height(70)
            .shadow({
              radius: this.shadowRadius,
              color: this.shadowColor,
              offsetX: 5,
              offsetY: 5
            })
            .border({ width: 1, color: Color.Gray })
          Text('Shadow')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.svg'))
            .width(70)
            .height(70)
            .shadow({
              radius: this.shadowRadius,
              color: Color.Red,
              offsetX: -5,
              offsetY: -5
            })
            .border({ width: 1, color: Color.Gray })
          Text('Red Shadow')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.icon'))
            .width(70)
            .height(70)
            .shadow({
              radius: this.shadowRadius,
              color: Color.Blue,
              offsetX: 0,
              offsetY: 10
            })
            .border({ width: 1, color: Color.Gray })
          Text('Blue Shadow')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.star'))
            .width(70)
            .height(70)
            .shadow({
              radius: this.shadowRadius,
              color: Color.Green,
              offsetX: 10,
              offsetY: 0
            })
            .border({ width: 1, color: Color.Gray })
          Text('Green Shadow')
            .fontSize(12)
        }
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)

      Slider({
        value: this.shadowRadius,
        min: 0,
        max: 30,
        step: 1
      })
        .width('90%')
        .onChange((value: number) => {
          this.shadowRadius = value
        })

      Row({ space: 10 }) {
        ForEach([Color.Black, Color.Red, Color.Blue, Color.Green], (color: Color) => {
          Button('')
            .width(30)
            .height(30)
            .backgroundColor(color)
            .borderRadius(15)
            .onClick(() => {
              this.shadowColor = color
            })
        })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .padding(10)
    .backgroundColor(Color.White)
    .borderRadius(10)
  }

  @Builder
  GradientEffectSection() {
    Column({ space: 15 }) {
      Text('Gradient Effect')
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .width('100%')

      Row({ space: 15 }) {
        Column({ space: 5 }) {
          Image($r('app.media.testSvg'))
            .width(80)
            .height(80)
            .linearGradient({
              angle: this.gradientAngle,
              colors: this.gradientColors
            })
            .border({ width: 1, color: Color.Gray })
          Text('Linear')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.svg'))
            .width(80)
            .height(80)
            .linearGradient({
              direction: GradientDirection.Right,
              colors: [[0xFF0000, 0.0], [0x00FF00, 0.5], [0x0000FF, 1.0]]
            })
            .border({ width: 1, color: Color.Gray })
          Text('RGB Gradient')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.icon'))
            .width(80)
            .height(80)
            .linearGradient({
              direction: GradientDirection.Bottom,
              colors: [[0xFFFFFF, 0.0], [0x000000, 1.0]]
            })
            .border({ width: 1, color: Color.Gray })
          Text('Grayscale')
            .fontSize(12)
        }
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)

      Slider({
        value: this.gradientAngle,
        min: 0,
        max: 360,
        step: 15
      })
        .width('90%')
        .onChange((value: number) => {
          this.gradientAngle = value
        })

      Text('Angle: ' + this.gradientAngle.toFixed(0) + '°')
        .fontSize(12)
        .fontColor(Color.Gray)
    }
    .width('100%')
    .padding(10)
    .backgroundColor(Color.White)
    .borderRadius(10)
  }

  @Builder
  TransformEffectSection() {
    Column({ space: 15 }) {
      Text('Transform Effect')
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .width('100%')

      Row({ space: 15 }) {
        Column({ space: 5 }) {
          Image($r('app.media.testSvg'))
            .width(60)
            .height(60)
            .rotate({ angle: this.rotateAngle })
            .border({ width: 1, color: Color.Gray })
          Text('Rotate')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.svg'))
            .width(60)
            .height(60)
            .scale({ x: this.scaleValue, y: this.scaleValue })
            .border({ width: 1, color: Color.Gray })
          Text('Scale')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.icon'))
            .width(60)
            .height(60)
            .translate({ x: this.translateX, y: this.translateY })
            .border({ width: 1, color: Color.Gray })
          Text('Translate')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.star'))
            .width(60)
            .height(60)
            .rotate({ angle: this.rotateAngle })
            .scale({ x: this.scaleValue, y: this.scaleValue })
            .border({ width: 1, color: Color.Gray })
          Text('Combined')
            .fontSize(12)
        }
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)

      Column({ space: 10 }) {
        Row({ space: 10 }) {
          Text('Rotate:')
            .width(70)
            .fontSize(12)
          Slider({
            value: this.rotateAngle,
            min: 0,
            max: 360,
            step: 1
          })
            .width('60%')
            .onChange((value: number) => {
              this.rotateAngle = value
            })
        }
        .width('100%')

        Row({ space: 10 }) {
          Text('Scale:')
            .width(70)
            .fontSize(12)
          Slider({
            value: this.scaleValue,
            min: 0.5,
            max: 2.0,
            step: 0.1
          })
            .width('60%')
            .onChange((value: number) => {
              this.scaleValue = value
            })
        }
        .width('100%')

        Row({ space: 10 }) {
          Text('TranslateX:')
            .width(70)
            .fontSize(12)
          Slider({
            value: this.translateX,
            min: -50,
            max: 50,
            step: 1
          })
            .width('60%')
            .onChange((value: number) => {
              this.translateX = value
            })
        }
        .width('100%')

        Row({ space: 10 }) {
          Text('TranslateY:')
            .width(70)
            .fontSize(12)
          Slider({
            value: this.translateY,
            min: -50,
            max: 50,
            step: 1
          })
            .width('60%')
            .onChange((value: number) => {
              this.translateY = value
            })
        }
        .width('100%')
      }
      .width('100%')
    }
    .width('100%')
    .padding(10)
    .backgroundColor(Color.White)
    .borderRadius(10)
  }

  @Builder
  AnimationEffectSection() {
    Column({ space: 15 }) {
      Text('Animation Effect')
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .width('100%')

      Row({ space: 15 }) {
        Column({ space: 5 }) {
          Image($r('app.media.testSvg'))
            .width(70)
            .height(70)
            .rotate({ angle: this.animAngle })
            .animation({
              duration: this.animationDuration,
              curve: Curve.Linear,
              iterations: -1
            })
            .border({ width: 1, color: Color.Gray })
          Text('Rotate')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.svg'))
            .width(70)
            .height(70)
            .scale({ x: this.animScale, y: this.animScale })
            .animation({
              duration: this.animationDuration,
              curve: Curve.EaseInOut,
              iterations: -1,
              playMode: PlayMode.Alternate
            })
            .border({ width: 1, color: Color.Gray })
          Text('Scale')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.icon'))
            .width(70)
            .height(70)
            .opacity(this.animOpacity)
            .animation({
              duration: this.animationDuration,
              curve: Curve.EaseInOut,
              iterations: -1,
              playMode: PlayMode.Alternate
            })
            .border({ width: 1, color: Color.Gray })
          Text('Opacity')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.star'))
            .width(70)
            .height(70)
            .translate({ x: this.animX })
            .animation({
              duration: this.animationDuration,
              curve: Curve.EaseInOut,
              iterations: -1,
              playMode: PlayMode.Alternate
            })
            .border({ width: 1, color: Color.Gray })
          Text('Translate')
            .fontSize(12)
        }
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)

      Row({ space: 10 }) {
        Button('Start')
          .onClick(() => {
            this.isAnimating = true
            this.animAngle = 360
            this.animScale = 1.5
            this.animOpacity = 0.3
            this.animX = 30
          })

        Button('Stop')
          .onClick(() => {
            this.isAnimating = false
            this.animAngle = 0
            this.animScale = 1.0
            this.animOpacity = 1.0
            this.animX = 0
          })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)

      Row({ space: 10 }) {
        Text('Duration:')
          .fontSize(12)
        Slider({
          value: this.animationDuration,
          min: 500,
          max: 5000,
          step: 100
        })
          .width('70%')
          .onChange((value: number) => {
            this.animationDuration = value
          })
      }
      .width('100%')

      Text('Duration: ' + this.animationDuration + 'ms')
        .fontSize(12)
        .fontColor(Color.Gray)
    }
    .width('100%')
    .padding(10)
    .backgroundColor(Color.White)
    .borderRadius(10)
  }

  @Builder
  MaskEffectSection() {
    Column({ space: 15 }) {
      Text('Mask Effect')
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .width('100%')

      Row({ space: 15 }) {
        Column({ space: 5 }) {
          Stack() {
            Image($r('app.media.testSvg'))
              .width(80)
              .height(80)
          }
          .width(80)
          .height(80)
          .mask(new Circle({ width: 80, height: 80 }))
          .border({ width: 1, color: Color.Gray })

          Text('Circle Mask')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Stack() {
            Image($r('app.media.svg'))
              .width(80)
              .height(80)
          }
          .width(80)
          .height(80)
          .mask(new Rect({ width: 80, height: 80 }))
          .border({ width: 1, color: Color.Gray })

          Text('Rect Mask')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Stack() {
            Image($r('app.media.icon'))
              .width(80)
              .height(80)
          }
          .width(80)
          .height(80)
          .mask(new Ellipse({ width: 80, height: 60 }))
          .border({ width: 1, color: Color.Gray })

          Text('Ellipse Mask')
            .fontSize(12)
        }
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)

      Row({ space: 15 }) {
        Column({ space: 5 }) {
          Stack() {
            Image($r('app.media.star'))
              .width(80)
              .height(80)
              .fillColor(Color.Red)
          }
          .width(80)
          .height(80)
          .mask(new Path({ width: 80, height: 80, commands: 'M40 0 L80 80 L0 80 Z' }))
          .border({ width: 1, color: Color.Gray })

          Text('Triangle Mask')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Stack() {
            Image($r('app.media.heart'))
              .width(80)
              .height(80)
              .fillColor(Color.Pink)
          }
          .width(80)
          .height(80)
          .borderRadius(20)
          .clip(true)
          .border({ width: 1, color: Color.Gray })

          Text('RoundRect Mask')
            .fontSize(12)
        }
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .padding(10)
    .backgroundColor(Color.White)
    .borderRadius(10)
  }

  @Builder
  ClipEffectSection() {
    Column({ space: 15 }) {
      Text('Clip Effect')
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .width('100%')

      Row({ space: 15 }) {
        Column({ space: 5 }) {
          Image($r('app.media.testSvg'))
            .width(80)
            .height(80)
            .clip(new Circle({ width: 80, height: 80 }))
            .border({ width: 1, color: Color.Gray })
          Text('Circle Clip')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.svg'))
            .width(80)
            .height(80)
            .clip(new Rect({ width: 80, height: 80 }))
            .border({ width: 1, color: Color.Gray })
          Text('Rect Clip')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.icon'))
            .width(80)
            .height(80)
            .clip(new Ellipse({ width: 80, height: 60 }))
            .border({ width: 1, color: Color.Gray })
          Text('Ellipse Clip')
            .fontSize(12)
        }
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)

      Row({ space: 15 }) {
        Column({ space: 5 }) {
          Image($r('app.media.star'))
            .width(80)
            .height(80)
            .fillColor(Color.Orange)
            .clip(new Path({ width: 80, height: 80, commands: 'M40 0 L80 80 L0 80 Z' }))
            .border({ width: 1, color: Color.Gray })
          Text('Triangle Clip')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.heart'))
            .width(80)
            .height(80)
            .fillColor(Color.Red)
            .borderRadius(15)
            .clip(true)
            .border({ width: 1, color: Color.Gray })
          Text('RoundRect Clip')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.testSvg'))
            .width(80)
            .height(80)
            .borderRadius(40)
            .clip(true)
            .border({ width: 1, color: Color.Gray })
          Text('BorderRadius')
            .fontSize(12)
        }
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
    }
    .width('100%')
    .padding(10)
    .backgroundColor(Color.White)
    .borderRadius(10)
  }

  @Builder
  FilterEffectSection() {
    Column({ space: 15 }) {
      Text('Filter Effect')
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .width('100%')

      Row({ space: 15 }) {
        Column({ space: 5 }) {
          Image($r('app.media.testSvg'))
            .width(70)
            .height(70)
            .brightness(this.brightnessValue)
            .border({ width: 1, color: Color.Gray })
          Text('Brightness')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.svg'))
            .width(70)
            .height(70)
            .contrast(this.contrastValue)
            .border({ width: 1, color: Color.Gray })
          Text('Contrast')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.icon'))
            .width(70)
            .height(70)
            .saturate(this.saturateValue)
            .border({ width: 1, color: Color.Gray })
          Text('Saturate')
            .fontSize(12)
        }

        Column({ space: 5 }) {
          Image($r('app.media.star'))
            .width(70)
            .height(70)
            .invert(this.invertValue)
            .border({ width: 1, color: Color.Gray })
          Text('Invert')
            .fontSize(12)
        }
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)

      Column({ space: 8 }) {
        Row({ space: 10 }) {
          Text('Brightness:')
            .width(80)
            .fontSize(12)
          Slider({
            value: this.brightnessValue,
            min: 0,
            max: 2,
            step: 0.1
          })
            .width('60%')
            .onChange((value: number) => {
              this.brightnessValue = value
            })
        }
        .width('100%')

        Row({ space: 10 }) {
          Text('Contrast:')
            .width(80)
            .fontSize(12)
          Slider({
            value: this.contrastValue,
            min: 0,
            max: 2,
            step: 0.1
          })
            .width('60%')
            .onChange((value: number) => {
              this.contrastValue = value
            })
        }
        .width('100%')

        Row({ space: 10 }) {
          Text('Saturate:')
            .width(80)
            .fontSize(12)
          Slider({
            value: this.saturateValue,
            min: 0,
            max: 2,
            step: 0.1
          })
            .width('60%')
            .onChange((value: number) => {
              this.saturateValue = value
            })
        }
        .width('100%')

        Row({ space: 10 }) {
          Text('Invert:')
            .width(80)
            .fontSize(12)
          Slider({
            value: this.invertValue,
            min: 0,
            max: 1,
            step: 0.1
          })
            .width('60%')
            .onChange((value: number) => {
              this.invertValue = value
            })
        }
        .width('100%')
      }
      .width('100%')
    }
    .width('100%')
    .padding(10)
    .backgroundColor(Color.White)
